package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.Test;

/**
 * Gap-analysis G1/G2: the linear-chained hash table records its duplicate-chain statistics at build time (chain-length
 * per bucket, max, mean) and lets a probe consume a chain <em>handle's count</em> instead of walking the chain — the
 * first escape of chain structure out of the flat probe loop. The payload-free counted mode is the post-build
 * representation revision: with duplicate keys and no payload slots every chain element would merge an identical output
 * row, so the probe multiplies instead of chasing {@code next[]} pointers.
 */
public class LmdbNativeHashJoinChainStatsTest {

	@Test
	public void buildTimeChainStatisticsTrackDuplicates() {
		PrimitiveHashJoinTable table = new PrimitiveHashJoinTable(1, 1);
		int[] keySlots = { 0 };
		int[] payloadSlots = { 1 };

		table.add(new long[] { 100, 1 }, keySlots, payloadSlots);
		table.add(new long[] { 100, 2 }, keySlots, payloadSlots);
		table.add(new long[] { 100, 3 }, keySlots, payloadSlots);
		table.add(new long[] { 200, 4 }, keySlots, payloadSlots);

		assertThat(table.distinctKeys).isEqualTo(2);
		assertThat(table.uniqueKeys).isFalse();
		assertThat(table.maxChainLength()).as("the hot key's chain length").isEqualTo(3);
		assertThat(table.meanChainLength()).as("4 payload rows over 2 distinct keys").isEqualTo(2D);
	}

	/** The per-bucket counts must survive the rehash that bucket growth performs. */
	@Test
	public void chainStatisticsSurviveBucketGrowth() {
		PrimitiveHashJoinTable table = new PrimitiveHashJoinTable(1, 0);
		int[] keySlots = { 0 };
		int[] payloadSlots = {};

		for (int i = 0; i < 3; i++) {
			table.add(new long[] { 7 }, keySlots, payloadSlots);
		}
		// push past the 32-bucket load factor so growBuckets() rehashes at least once
		for (long key = 100; key < 160; key++) {
			table.add(new long[] { key }, keySlots, payloadSlots);
		}

		assertThat(table.distinctKeys).isEqualTo(61);
		assertThat(table.maxChainLength()).as("the hot chain's length survives rehashing").isEqualTo(3);
		assertThat(table.meanChainLength()).isEqualTo(63D / 61D);
	}

	/** The chain handle's count is resolvable straight from a prepared probe, without walking the chain. */
	@Test
	public void countedChainLookupResolvesWithoutWalkingTheChain() {
		PrimitiveHashJoinTable table = new PrimitiveHashJoinTable(1, 0);
		int[] keySlots = { 0 };
		int[] payloadSlots = {};
		table.add(new long[] { 42 }, keySlots, payloadSlots);
		table.add(new long[] { 42 }, keySlots, payloadSlots);
		table.add(new long[] { 99 }, keySlots, payloadSlots);

		NativeBatch probe = new NativeBatch(1, 4);
		probe.set(0, 0, 42);
		probe.set(0, 1, 99);
		probe.set(0, 2, 7);
		probe.finishRows(3);
		long[] hashState = new long[4];
		int[] hashes = new int[4];
		int[] buckets = new int[4];
		int[] heads = new int[4];
		table.hashBatch(probe, probe.selection, 3, keySlots, hashState, hashes);
		table.headBatch(hashes, 3, buckets, heads);

		assertThat(table.lookupPreparedChainCount(probe, 0, keySlots, hashes[0], buckets[0]))
				.as("duplicate key resolves its chain count")
				.isEqualTo(2);
		assertThat(table.lookupPreparedChainCount(probe, 1, keySlots, hashes[1], buckets[1]))
				.as("singleton key resolves count 1")
				.isEqualTo(1);
		assertThat(table.lookupPreparedChainCount(probe, 2, keySlots, hashes[2], buckets[2]))
				.as("missing key resolves count 0")
				.isEqualTo(0);
	}

	// NOTE: the natural end-to-end guard for the counted-chain mode — a payload-free build side with keys
	// duplicated across named graphs — cannot pass on this branch tip: the DEFAULT strategy path already loses
	// rows for that exact fixture (native 2060 of 8400, proven at pure HEAD with a clean production tree and
	// reported separately). Once that row-loss bug is fixed, add the differential here: 4200 probe rows
	// (a{i}, p, s{i%500}) against 500 duplicated (s{k}, q, c) rows in two graphs must yield 8400 rows.
}
